def due(self, merchant: str, ts: int) -> list[Charge]:
    """The merchant's unsettled charges whose funds are available at ts, earliest
    available_on first (capture order breaks ties). A charge counts as settled once
    its batch is set."""
    out = [c for c in self.pending.get(merchant, []) if c.batch == "" and c.available_on <= ts]
    out.sort(key=lambda c: (c.available_on, c.seq))
    return out
